llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Carbamazepine epoxide, the closest analogue (the 10,11-epoxide of the query), had an absolute oral bioavailability of 60% (95% CI 49–75%) in healthy subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Oxcarbazepine, a close tricyclic dibenzoazepine carboxamide analogue, has almost complete oral bioavailability (95%) in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Licarbazepine, the active metabolite of oxcarbazepine, had a mean absolute bioavailability of 89% after oral 300 mg versus IV in healthy adults.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Eslicarbazepine, the active metabolite of eslicarbazepine acetate, has approximately 94% oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "PEMA, a structurally simpler phenyl/amide analogue, has almost complete absolute bioavailability (91 ± 4.4%) in normal volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Sulpiride, a lower-similarity benzamide, has a mean oral bioavailability of about 35% (range 10–70%), still above the 20% threshold on average.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Zileuton, a low-similarity lipophilic drug, was reported to have poor oral bioavailability; however, its structural distance and lack of quantitative F limit its relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is carbamazepine. The closest analogue, carbamazepine epoxide, has absolute F ~60% (≥57–78%), and close tricyclic dibenzoazepine carboxamide analogues (oxcarbazepine, licarbazepine, eslicarbazepine) show 89–99% oral bioavailability. These direct experimental data strongly support F ≥ 20%; the low-similarity zileuton poor-bioavailability report is insufficient to overturn.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for carbamazepine itself is included in the provided evidence; the closest is carbamazepine epoxide.",
    "The zileuton poor-bioavailability record is qualitative and lacks a quantitative F value.",
    "Carbamazepine's low aqueous solubility may slow absorption but does not necessarily reduce the extent of bioavailability below 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

